entries[29714] = { ["name"] = "Pattern: Drums of Restoration", ["text"] = "Use: Teaches you how to make Drums of Restoration.\nRequires Outland Leatherworking (50)\nSell Price:\nDrums of Restoration\nUse: Restores 170 health and mana to nearby party members over 15 sec. Cannot affect targets above level 50. (2 Min Cooldown)\n50 Charges\nRequires Outland Leatherworking (50)\nSell Price:\nRequires Heavy Knothide Leather (6), Nether Dragonscales (4)" }
