entries[29718] = { ["name"] = "Pattern: Drums of Speed", ["text"] = "Use: Teaches you how to make Drums of Speed.\nRequires Outland Leatherworking (45)\nSell Price:\nDrums of Speed\nUse: Increases movement speed of nearby party members by 15%. Lasts 30 sec. Cannot be used beyond level 35. (2 Min Cooldown)\n50 Charges\nRequires Outland Leatherworking (40)\nSell Price:\nRequires Heavy Knothide Leather (6), Wind Scales (4)" }
entries[29719] = { ["name"] = "Pattern: Cobrahide Leg Armor", ["text"] = "Binds when picked up\nUse: Teaches you how to make Cobrahide Leg Armor.\nRequires Outland Leatherworking (35)\nRequires Honor Hold\n- Honored\nSell Price:\nCobrahide Leg Armor\nUse: Permanently attach cobrahide armor onto pants to increase attack power by 2 and critical strike by 3. Enchanting the item causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Heavy Knothide Leather (4), Cobra Scales (2), Primal Air (4)" }
